-- Catalogue central des besoins v1.0 : 30 catégories, sous-catégories, 8 familles d'affichage.
ALTER TABLE categories ADD COLUMN position INT NOT NULL DEFAULT 0, ADD COLUMN active BOOLEAN NOT NULL DEFAULT TRUE,
  ADD COLUMN sensitive BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN names JSONB NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE families (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '',
  position INT NOT NULL DEFAULT 0, names JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE category_families (
  category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE, family_id UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  position INT NOT NULL DEFAULT 0, PRIMARY KEY (category_id, family_id));
CREATE TABLE subcategories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
  name TEXT NOT NULL, slug TEXT NOT NULL, position INT NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE,
  names JSONB NOT NULL DEFAULT '{}'::jsonb, UNIQUE (category_id, slug));
-- Fiche détaillée d'un besoin (Catalogue §4) ; plusieurs catégories possibles (§5 règle 1)
ALTER TABLE needs
  ADD COLUMN nature TEXT CHECK (nature IN ('materiel','financier','humain','technique','informationnel','autre')),
  ADD COLUMN frequency TEXT CHECK (frequency IN ('ponctuel','occasionnel','regulier','permanent')),
  ADD COLUMN priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('faible','normal','eleve','urgent')),
  ADD COLUMN country TEXT,
  ADD COLUMN support_type TEXT CHECK (support_type IN ('aide_directe','orientation','mise_en_relation','conseil','formation')),
  ADD COLUMN confidentiality TEXT NOT NULL DEFAULT 'private' CHECK (confidentiality IN ('public','organizations','private'));
CREATE TABLE need_categories (
  need_id UUID NOT NULL REFERENCES needs(id) ON DELETE CASCADE, category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
  subcategory_id UUID REFERENCES subcategories(id) ON DELETE SET NULL, PRIMARY KEY (need_id, category_id));

